import { FaCheckCircle, FaCircle, FaPlus, FaCalendarAlt } from 'react-icons/fa';
import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { 
    Calendar, Check, X, Plus, RefreshCw, 
    Save, FileText, Clock, MessageSquare,
    Eye, Target, Users
} from 'lucide-react';
import axios from 'axios';
import toast from 'react-hot-toast';

const DailyTracker = () => {
    const { user, token } = useAuth();
    const [tasks, setTasks] = useState([]);
    const [selectedDay, setSelectedDay] = useState(null);
    const [loading, setLoading] = useState(true);
    const [creating, setCreating] = useState(false);
    const [selectedTask, setSelectedTask] = useState(null);
    const [taskNote, setTaskNote] = useState('');
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [showHistory, setShowHistory] = useState(false);
    
    // Get current date
    const today = new Date();
    const currentMonth = today.getMonth();
    const currentYear = today.getFullYear();
    const currentDay = today.getDate();
    
    // Target: November 30, 2026
    const targetDate = new Date(2026, 10, 30);
    const daysRemaining = Math.max(0, Math.ceil((targetDate - today) / (1000 * 60 * 60 * 24)));
    
    const getDaysInMonth = (month, year) => {
        return new Date(year, month + 1, 0).getDate();
    };
    
    const daysInMonth = getDaysInMonth(currentMonth, currentYear);
    const monthNames = ['January', 'February', 'March', 'April', 'May', 'June', 
                        'July', 'August', 'September', 'October', 'November', 'December'];

    useEffect(() => {
        if (user) {
            console.log('User loaded:', user);
            fetchTasks();
        }
    }, [user]);

    const fetchTasks = async () => {
        try {
            console.log('Fetching tasks for user:', user.id);
            const response = await axios.get(
                `http://localhost:8081/api/tasks/user/${user.id}`,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            console.log('Tasks fetched:', response.data);
            setTasks(response.data);
            setLoading(false);
        } catch (error) {
            console.error('Failed to fetch tasks:', error);
            toast.error('Failed to load tasks');
            setLoading(false);
        }
    };

    const createTaskForDay = async (day) => {
        setCreating(true);
        try {
            const date = new Date(currentYear, currentMonth, day);
            const dateStr = date.toISOString().split('T')[0];
            
            console.log('Creating task for day:', day, 'date:', dateStr);
            
            const response = await axios.post(
                `http://localhost:8081/api/tasks/user/${user.id}/day/${day}?date=${dateStr}`,
                {},
                { 
                    headers: { 
                        'Authorization': `Bearer ${token}`,
                        'Content-Type': 'application/json'
                    } 
                }
            );
            console.log('Task created:', response.data);
            setTasks([...tasks, response.data]);
            toast.success(`Tasks created for ${monthNames[currentMonth]} ${day}`);
            return response.data;
        } catch (error) {
            console.error('Failed to create task:', error);
            if (error.response) {
                toast.error(`Error: ${error.response.status} - ${error.response.data?.message || 'Failed to create tasks'}`);
            } else if (error.request) {
                toast.error('Backend not responding! Make sure backend is running on port 8081');
            } else {
                toast.error('Failed to create tasks: ' + error.message);
            }
            return null;
        } finally {
            setCreating(false);
        }
    };

    const toggleTask = async (taskId, field) => {
        console.log('Toggling task:', taskId, field);
        
        if (!taskId) {
            console.error('No task ID provided');
            toast.error('Task ID missing');
            return;
        }
        
        const task = tasks.find(t => t.id === taskId);
        if (!task) {
            console.error('Task not found with ID:', taskId);
            toast.error('Task not found');
            return;
        }

        const updatedTask = { 
            ...task, 
            [field]: !task[field] 
        };
        
        console.log('Sending updated task:', updatedTask);
        
        try {
            const response = await axios.put(
                `http://localhost:8081/api/tasks/${taskId}`,
                updatedTask,
                { 
                    headers: { 
                        'Authorization': `Bearer ${token}`,
                        'Content-Type': 'application/json'
                    } 
                }
            );
            console.log('Task updated:', response.data);
            setTasks(tasks.map(t => t.id === taskId ? response.data : t));
            toast.success('✅ Alhamdulillah!');
        } catch (error) {
            console.error('Failed to update task - FULL ERROR:', error);
            console.error('Error response:', error.response);
            console.error('Error message:', error.message);
            
            if (error.response) {
                toast.error(`Error ${error.response.status}: ${error.response.data?.message || 'Failed to update'}`);
            } else if (error.request) {
                toast.error('Backend not responding! Check if backend is running on port 8081');
            } else {
                toast.error('Failed to update: ' + error.message);
            }
        }
    };

    const updateTaskNote = async (taskId, note) => {
        const task = tasks.find(t => t.id === taskId);
        if (!task) return;

        const updatedTask = { ...task, notes: note };
        
        try {
            const response = await axios.put(
                `http://localhost:8081/api/tasks/${taskId}`,
                updatedTask,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setTasks(tasks.map(t => t.id === taskId ? response.data : t));
            toast.success('Note saved! 💾');
        } catch (error) {
            console.error('Failed to save note:', error);
            toast.error('Failed to save note');
        }
    };

    const handleDayClick = async (day) => {
        console.log('Day clicked:', day);
        setSelectedDay(day);
        const dayTasks = tasks.filter(task => task.day === day);
        console.log('Tasks for day:', dayTasks);
        if (dayTasks.length === 0 && !creating) {
            await createTaskForDay(day);
        }
    };

    const handleTaskClick = (task, field) => {
        const labels = {
            javaCompleted: 'Java',
            leetcodeCompleted: 'LeetCode',
            dsaCompleted: 'DSA/OOP',
            sqlCompleted: 'SQL/APIs',
            projectCompleted: 'Project',
            githubCompleted: 'GitHub/Portfolio'
        };
        setSelectedTask({ task, field, label: labels[field] });
        setTaskNote(task.notes || '');
        setIsModalOpen(true);
    };

    const saveNote = () => {
        if (selectedTask) {
            updateTaskNote(selectedTask.task.id, taskNote);
            setIsModalOpen(false);
        }
    };

    const getDayTasks = (day) => tasks.filter(task => task.day === day);

    const getDayStatus = (day) => {
        const dayTasks = getDayTasks(day);
        if (dayTasks.length === 0) return 'empty';
        const completed = dayTasks.filter(t => t.overallCompleted).length;
        if (completed === dayTasks.length) return 'done';
        if (completed > 0) return 'partial';
        return 'started';
    };

    const tasksWithNotes = tasks.filter(t => t.notes && t.notes.trim() !== '');
    const totalCompleted = tasks.filter(t => t.overallCompleted).length;
    const totalTasks = tasks.length;
    const progressPercent = totalTasks > 0 ? Math.round((totalCompleted / totalTasks) * 100) : 0;

    if (loading) {
        return (
            <div className="flex items-center justify-center h-64">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
            </div>
        );
    }

    const taskLabels = [
        { key: 'javaCompleted', label: '☕ Java (1.5h)', icon: '📚' },
        { key: 'leetcodeCompleted', label: '💻 LeetCode (1+)', icon: '🎯' },
        { key: 'dsaCompleted', label: '📊 DSA/OOP (1h)', icon: '🧩' },
        { key: 'sqlCompleted', label: '🗄️ SQL/APIs (1h)', icon: '🔗' },
        { key: 'projectCompleted', label: '🚀 Project (2-3h)', icon: '⚡' },
        { key: 'githubCompleted', label: '📁 GitHub/Portfolio', icon: '📝' }
    ];

    const calendarDays = [];
    for (let day = 1; day <= daysInMonth; day++) {
        calendarDays.push(day);
    }

    const weekDays = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

    return (
        <>
            {/* Modal for notes */}
            {isModalOpen && selectedTask && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50">
                    <div className="bg-white rounded-2xl max-w-md w-full p-6 shadow-2xl">
                        <div className="flex items-center justify-between mb-4">
                            <div>
                                <h3 className="text-xl font-bold text-gray-800">
                                    {selectedTask.label} - {monthNames[currentMonth]} {selectedTask.task.day}
                                </h3>
                                <p className="text-sm text-gray-500">📝 Add your learning notes</p>
                            </div>
                            <button 
                                onClick={() => setIsModalOpen(false)}
                                className="p-2 hover:bg-gray-100 rounded-lg"
                            >
                                <X size={20} />
                            </button>
                        </div>
                        
                        <div className="mb-4">
                            <div className="flex items-center gap-2 text-sm text-gray-500 mb-2">
                                <MessageSquare size={16} />
                                <span>What did you learn today?</span>
                            </div>
                            <textarea
                                value={taskNote}
                                onChange={(e) => setTaskNote(e.target.value)}
                                placeholder="📝 Write what you studied, concepts learned, problems solved..."
                                className="w-full p-3 border border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-transparent resize-none h-32"
                            />
                        </div>
                        
                        <div className="flex gap-3">
                            <button
                                onClick={saveNote}
                                className="flex-1 bg-blue-600 text-white px-4 py-2 rounded-xl hover:bg-blue-700 transition flex items-center justify-center gap-2"
                            >
                                <Save size={18} />
                                Save Note 💾
                            </button>
                            <button
                                onClick={() => setIsModalOpen(false)}
                                className="px-4 py-2 border border-gray-200 rounded-xl hover:bg-gray-50 transition"
                            >
                                Cancel
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Main Content - Removed the outer white wrapper and max-width */}
            <div>
                {/* Header */}
                <div className="flex flex-wrap items-center justify-between mb-6 gap-4">
                    <div className="flex items-center gap-3">
                        <Calendar size={32} className="text-blue-600" />
                        <div>
                            <h1 className="text-2xl font-bold text-gray-800">
                                📅 {monthNames[currentMonth]} {currentYear}
                            </h1>
                            <div className="flex items-center gap-3 text-base text-gray-500">
                                <span>Today: <span className="font-bold text-gray-700">{currentDay} {monthNames[currentMonth]}</span></span>
                                <span className="w-1 h-1 bg-gray-300 rounded-full"></span>
                                <span className="flex items-center gap-1 text-orange-600 font-medium">
                                    <Target size={16} />
                                    {daysRemaining} days until target
                                </span>
                            </div>
                        </div>
                    </div>
                    <div className="flex items-center gap-3 flex-wrap">
                        <div className="bg-blue-50 px-4 py-2 rounded-full text-sm font-medium text-blue-600 flex items-center gap-1">
                            <Users size={16} />
                            {tasksWithNotes.length} notes
                        </div>
                        <div className="bg-green-50 px-4 py-2 rounded-full text-sm font-medium text-green-600 flex items-center gap-1">
                            <Check size={16} />
                            {progressPercent}% done
                        </div>
                        <button 
                            onClick={fetchTasks}
                            className="flex items-center gap-2 text-sm font-medium text-gray-500 hover:text-gray-700"
                        >
                            <RefreshCw size={16} />
                            Refresh
                        </button>
                    </div>
                </div>

                {/* Progress Bar */}
                <div className="mb-6 bg-gray-200 rounded-full h-3">
                    <div 
                        className="bg-gradient-to-r from-blue-500 to-purple-500 h-3 rounded-full transition-all duration-500"
                        style={{ width: `${progressPercent}%` }}
                    />
                </div>

                {/* Notes History */}
                {showHistory && tasksWithNotes.length > 0 && (
                    <div className="mb-6 bg-purple-50 rounded-xl p-4 border border-purple-200">
                        <div className="flex items-center justify-between mb-3">
                            <h4 className="font-semibold text-purple-800 flex items-center gap-2 text-lg">
                                <MessageSquare size={20} />
                                Communication Notes ({tasksWithNotes.length})
                            </h4>
                            <button 
                                onClick={() => setShowHistory(false)}
                                className="text-sm font-medium text-purple-600 hover:text-purple-800"
                            >
                                Close ✕
                            </button>
                        </div>
                        <div className="space-y-2 max-h-60 overflow-y-auto">
                            {tasksWithNotes.map((task) => {
                                return (
                                    <div key={task.id} className="bg-white rounded-lg p-3 border border-purple-100">
                                        <div className="flex items-center justify-between">
                                            <span className="text-sm font-medium text-gray-700">
                                                📅 {monthNames[currentMonth]} {task.day}
                                            </span>
                                            <span className="text-xs text-gray-400">
                                                {task.updatedAt ? new Date(task.updatedAt).toLocaleDateString() : 'Today'}
                                            </span>
                                        </div>
                                        <p className="text-sm text-gray-600 mt-1">{task.notes}</p>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                )}

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    {/* Calendar */}
                    <div className="lg:col-span-2">
                        <div className="grid grid-cols-7 gap-2">
                            {weekDays.map(day => (
                                <div key={day} className="text-center text-sm font-semibold text-gray-500 py-2">
                                    {day}
                                </div>
                            ))}
                            {calendarDays.map((day) => {
                                const status = getDayStatus(day);
                                let bgColor = 'bg-gray-100 hover:bg-gray-200';
                                let textColor = 'text-gray-700';
                                
                                if (status === 'done') {
                                    bgColor = 'bg-green-500 hover:bg-green-600 text-white';
                                    textColor = 'text-white';
                                } else if (status === 'partial') {
                                    bgColor = 'bg-yellow-400 hover:bg-yellow-500 text-white';
                                    textColor = 'text-white';
                                } else if (status === 'started') {
                                    bgColor = 'bg-blue-300 hover:bg-blue-400 text-white';
                                    textColor = 'text-white';
                                }
                                
                                const isSelected = selectedDay === day;
                                const isToday = day === currentDay && currentMonth === new Date().getMonth();
                                
                                return (
                                    <button
                                        key={day}
                                        onClick={() => handleDayClick(day)}
                                        className={`aspect-square rounded-xl flex items-center justify-center text-lg font-bold transition-all ${bgColor} ${textColor} ${isSelected ? 'ring-2 ring-blue-500 ring-offset-2' : ''} ${isToday ? 'ring-2 ring-red-500 ring-offset-2' : ''}`}
                                    >
                                        {day}
                                    </button>
                                );
                            })}
                        </div>

                        <div className="flex flex-wrap items-center gap-4 mt-4 text-sm font-medium text-gray-600">
                            <div className="flex items-center gap-1.5">
                                <div className="w-4 h-4 bg-green-500 rounded"></div>
                                <span>✅ Done</span>
                            </div>
                            <div className="flex items-center gap-1.5">
                                <div className="w-4 h-4 bg-yellow-400 rounded"></div>
                                <span>🟡 Partial</span>
                            </div>
                            <div className="flex items-center gap-1.5">
                                <div className="w-4 h-4 bg-blue-300 rounded"></div>
                                <span>🔵 Started</span>
                            </div>
                            <div className="flex items-center gap-1.5">
                                <div className="w-4 h-4 bg-gray-100 border border-gray-300 rounded"></div>
                                <span>⬜ Empty</span>
                            </div>
                            <div className="flex items-center gap-1.5">
                                <div className="w-4 h-4 ring-2 ring-red-500 ring-offset-1 bg-gray-100 rounded"></div>
                                <span>🔴 Today</span>
                            </div>
                        </div>
                    </div>

                    {/* Task List */}
                    <div className="bg-gray-50 rounded-xl p-4">
                        <div className="flex items-center justify-between mb-4">
                            <h3 className="text-lg font-bold text-gray-800">
                                {selectedDay ? `📋 Day ${selectedDay} Tasks` : 'Select a day'}
                            </h3>
                            {selectedDay && (
                                <button
                                    onClick={() => {
                                        const dayTasks = tasks.filter(t => t.day === selectedDay);
                                        if (dayTasks.length > 0 && dayTasks[0].notes) {
                                            setTaskNote(dayTasks[0].notes);
                                            setIsModalOpen(true);
                                        }
                                    }}
                                    className="text-sm font-medium text-blue-600 hover:text-blue-800"
                                >
                                    <MessageSquare size={18} />
                                </button>
                            )}
                        </div>
                        
                        {selectedDay ? (
                            <div className="space-y-3">
                                {taskLabels.map(({ key, label, icon }) => {
                                    const dayTasks = getDayTasks(selectedDay);
                                    const task = dayTasks.length > 0 ? dayTasks[0] : null;
                                    const isCompleted = task ? task[key] : false;
                                    const hasNote = task?.notes && task.notes.trim() !== '';
                                    
                                    return (
                                        <div
                                            key={key}
                                            className={`flex items-center justify-between p-3 rounded-xl transition-all ${
                                                isCompleted ? 'bg-green-50 border border-green-200' : 'bg-white border border-gray-200'
                                            }`}
                                        >
                                            <div className="flex items-center gap-3">
                                                <span className="text-2xl">{icon}</span>
                                                <div>
                                                    <p className={`text-base font-medium ${
                                                        isCompleted ? 'text-gray-400 line-through' : 'text-gray-700'
                                                    }`}>
                                                        {label}
                                                    </p>
                                                    {isCompleted && (
                                                        <p className="text-xs text-green-600 font-medium">
                                                            ✅ Alhamdulillah
                                                        </p>
                                                    )}
                                                </div>
                                            </div>
                                            <div className="flex items-center gap-2">
                                                {hasNote && (
                                                    <span className="text-xs text-blue-500 bg-blue-50 px-2 py-1 rounded-full">
                                                        📝
                                                    </span>
                                                )}
                                                <button
                                                    onClick={() => {
                                                        if (task && task.id) {
                                                            toggleTask(task.id, key);
                                                        } else {
                                                            toast.error('Task not found! Please create tasks first.');
                                                        }
                                                    }}
                                                    className={`px-4 py-2 rounded-xl text-sm font-medium transition-all ${
                                                        isCompleted 
                                                            ? 'bg-green-500 text-white hover:bg-green-600' 
                                                            : 'bg-blue-600 text-white hover:bg-blue-700'
                                                    }`}
                                                >
                                                    {isCompleted ? '✅ Alhamdulillah' : '☐ Mark Done'}
                                                </button>
                                            </div>
                                        </div>
                                    );
                                })}
                                
                                {getDayTasks(selectedDay).length === 0 && !creating && (
                                    <div className="text-center py-10">
                                        <p className="text-gray-500 text-base mb-4">📝 No tasks for this day</p>
                                        <button
                                            onClick={() => handleDayClick(selectedDay)}
                                            className="bg-blue-600 text-white px-6 py-3 rounded-xl text-base font-medium hover:bg-blue-700 transition flex items-center gap-2 mx-auto shadow-lg shadow-blue-200"
                                        >
                                            <Plus size={20} />
                                            Create Tasks
                                        </button>
                                    </div>
                                )}
                                
                                {creating && (
                                    <div className="text-center py-10">
                                        <div className="animate-spin rounded-full h-10 w-10 border-b-2 border-blue-600 mx-auto"></div>
                                        <p className="text-gray-500 text-base mt-3">Creating tasks...</p>
                                    </div>
                                )}
                            </div>
                        ) : (
                            <div className="flex items-center justify-center h-48 text-gray-400 text-base">
                                👆 Click a day on the calendar
                            </div>
                        )}
                    </div>
                </div>
                
                {/* Footer */}
                <div className="mt-6 pt-4 border-t border-gray-200 flex flex-wrap items-center justify-between gap-2">
                    <div className="flex items-center gap-2 text-sm text-gray-500">
                        <MessageSquare size={16} className="text-blue-500" />
                        <span>Click any task to add communication notes</span>
                    </div>
                    {tasksWithNotes.length > 0 && (
                        <button
                            onClick={() => setShowHistory(!showHistory)}
                            className="text-sm font-medium text-purple-600 hover:text-purple-800 flex items-center gap-1"
                        >
                            <Eye size={16} />
                            {showHistory ? 'Hide all notes' : `View all notes (${tasksWithNotes.length})`}
                        </button>
                    )}
                </div>
            </div>
        </>
    );
};

export default DailyTracker;
